# owner: platform
import unittest

from hourglass.rounding import round_spans
from hourglass.models import Span


class RoundSpansTests(unittest.TestCase):
    def test_label(self):
        self.assertEqual(
            round_spans([Span(9 * 60 + 2, 17 * 60 + 14)], 15),
            ["09:00-17:15 (8h 15m)"]
        )

    def test_rounds_down_below_half(self):
        self.assertEqual(
            round_spans([Span(547, 1020)], 15),
            ["09:00-17:00 (8h 00m)"]
        )

    def test_bad_steps(self):
        for step in (0, -5, 7, 45):
            with self.assertRaises(ValueError):
                round_spans([Span(0, 60)], step)
